import React from 'react';
import { Link } from 'react-router-dom';

const Home = () => {
  return (
    <div className="bg-gray-800 text-white min-h-screen">
      <header className="w-full bg-gray-900 p-4">
        <nav className="flex justify-between items-center w-full max-w-7xl mx-auto">
          <img src="logo.png" width="60" height="50" alt="Logo" />
          <div className="space-x-8">
          <Link to="/" className="hover:text-gray-400 text-white text-xl font-serif">Home</Link>
<Link to="/about" className="hover:text-gray-400 text-white text-xl font-serif">About</Link>
<Link to="/photography" className="hover:text-gray-400 text-white text-xl font-serif">Photography</Link>
<Link to="/portfolio" className="hover:text-gray-400 text-white text-xl font-serif">Portfolio</Link>

          </div>
        </nav>
      </header>

      <main className="p-8">
        <h1 className="text-4xl font-bold">Welcome to my homepage</h1>
        <p className="mt-4 text-lg">This is a simple page using React and Tailwind CSS.</p>
      </main>
    </div>
  );
};

export default Home;
